public class MathBox {
    static int square(int x) {
        return x * x;
    }

    public static int sumOfSquares(int[] xs) {
        int total = 0;
        for (int x : xs) {
            total += square(x);
        }
        return total;
    }

    public static int cube(int x) {
        return x * x * x;
    }
}

